using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Retrieve a specific configuration value by key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var config = new Dictionary<string, string>
        {
            ["app_name"] = "HttpMcpServer",
            ["version"] = "1.0.0",
            ["environment"] = "production",
            ["max_connections"] = "100"
        };

        return config.TryGetValue(key, out var value)
            ? value
            : $"Unknown key: {key}";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app", Name = "App Configuration",
        MimeType = "application/json")]
    [Description("Returns the full application configuration as JSON.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            AppName = "HttpMcpServer",
            Version = "1.0.0",
            Environment = "production",
            MaxConnections = 100,
            Features = new { Caching = true, RateLimiting = true }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions
        {
            WriteIndented = true
        });
    }

    [McpServerResource(UriTemplate = "config://endpoints", Name = "API Endpoints",
        MimeType = "application/json")]
    [Description("Returns the list of configured API endpoints.")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Name = "Users", Url = "/api/users", Method = "GET" },
            new { Name = "Orders", Url = "/api/orders", Method = "GET" },
            new { Name = "Health", Url = "/health", Method = "GET" }
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions
        {
            WriteIndented = true
        });
    }
}

